}

.settings-sidebar li.active {
    background: #0d6efd;
    color: #fff;
}

.settings-sidebar .sidebar-icon {
    font-size: 1.1rem;
}

.settings-content {
    flex: 1;
    padding: 2rem;
    overflow-y: auto;
}

