.settings-section h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    color: #333;
}

.appearance-form {
    max-width: 550px;
}

.form-group {
    margin-bottom: 1.25rem;
}

.group-label {
    display: block;
    font-weight: 600;
    margin-bottom: 0.5rem;
    font-size: 0.95rem;
    color: #555;
}

.radio-group {
    display: flex;
    gap: 1.5rem;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
    font-size: 0.95rem;
}

.radio-item input[type="radio"] {
    accent-color: #0d6efd;
}

select {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
    background: #fff;
}

.toggle-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
    font-size: 0.95rem;
}

.toggle-item input[type="checkbox"] {
    width: 18px;
    height: 18px;
    accent-color: #0d6efd;
}

/* Live Preview */
.preview-area {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 1.25rem;
    margin-bottom: 1.5rem;
    transition: all 0.3s ease;
}

.preview-area h4 {
    margin-top: 0;
    margin-bottom: 0.5rem;
}

.preview-text {
    margin-bottom: 0.75rem;
}

.preview-card {
    background: #f0f0f0;
    border-radius: 4px;
    padding: 0.75rem;
}

.preview-card p {
    margin: 0.25rem 0 0;
    font-size: 0.9em;
}

/* Theme variants */
.preview-light {
    background: #ffffff;
    color: #333;
}

.preview-dark {
    background: #1e1e2e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-dark .preview-card {
    background: #2d2d3d;
    color: #ccc;
}

.preview-system {
    background: #f5f5f5;
    color: #333;
    border-color: #bbb;
}

/* Font size variants */
.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
